import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.DGzjq_gw.js";const p=JSON.parse('{"title":"React / Vue 高频题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/framework-questions.md","filePath":"interview/framework-questions.md","lastUpdated":1792491378000}'),c={name:"interview/framework-questions.md"};function d(r,e,n,i,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="react-vue-高频题" tabindex="-1">React / Vue 高频题 <a class="header-anchor" href="#react-vue-高频题" aria-label="Permalink to &quot;React / Vue 高频题&quot;">​</a></h1><p>本页覆盖框架层的高频题，采用 <strong>[问法] → [要点] → [深度补充]</strong> 结构。9 份 JD 中多数要求&quot;熟练 React 或 Vue，且多数要求双栈&quot;，因此<strong>双栈对比题</strong>是必答项。对应 JD 要求 A1（熟练双栈）。</p><blockquote><p>机制细节见 <a href="/frontend-kb-pages/framework/react">React 18/19 深入</a>、<a href="/frontend-kb-pages/framework/vue">Vue 3 深入</a>、<a href="/frontend-kb-pages/framework/dual-stack">双栈对比</a>。</p></blockquote><h2 id="一、react-hooks-与渲染原理" tabindex="-1">一、React：Hooks 与渲染原理 <a class="header-anchor" href="#一、react-hooks-与渲染原理" aria-label="Permalink to &quot;一、React：Hooks 与渲染原理&quot;">​</a></h2><h3 id="q1-为什么-hooks-有调用规则-不能在条件-循环里调用" tabindex="-1">Q1. 为什么 Hooks 有调用规则（不能在条件/循环里调用）？ <a class="header-anchor" href="#q1-为什么-hooks-有调用规则-不能在条件-循环里调用" aria-label="Permalink to &quot;Q1. 为什么 Hooks 有调用规则（不能在条件/循环里调用）？&quot;">​</a></h3><p><strong>要点</strong>：React 用<strong>链表</strong>按调用顺序存每个 Hook 的状态，靠&quot;调用顺序&quot;把 <code>useState</code>、<code>useEffect</code> 与内部 <code>memoizedState</code> 一一对应。顺序变了，状态就会错位。所以必须在顶层调用、顺序稳定。</p><p><strong>深度补充</strong>：规则由 <code>eslint-plugin-react-hooks</code> 静态约束；Hooks 只能在函数组件或自定义 Hook 内调用。多个 Hook 通过 <code>next</code> 指针串成链表，重渲染时按序读取，这就是&quot;顺序敏感&quot;的根因。</p><h3 id="q2-usestate-的更新为什么是异步批处理的" tabindex="-1">Q2. <code>useState</code> 的更新为什么是异步批处理的？ <a class="header-anchor" href="#q2-usestate-的更新为什么是异步批处理的" aria-label="Permalink to &quot;Q2. `useState` 的更新为什么是异步批处理的？&quot;">​</a></h3><p><strong>要点</strong>：React 18 之前只在 React 事件中批处理；React 18 起用 <code>createRoot</code> 后，<strong>所有</strong>更新（含 <code>setTimeout</code>、<code>Promise</code>、原生事件）都自动批处理。<code>setState</code> 传函数可基于前值更新，避免闭包旧值问题。</p><p><strong>深度补充</strong>：连续 <code>setCount(count + 1)</code> 三次只 +1（因为 <code>count</code> 是同一渲染期的旧值）；写成 <code>setCount((c) =&gt; c + 1)</code> 三次才 +3。批处理由 <code>Automatic Batching</code> 的调度器统一 flush，减少渲染次数。</p><h3 id="q3-useeffect-的依赖数组与执行时机" tabindex="-1">Q3. <code>useEffect</code> 的依赖数组与执行时机？ <a class="header-anchor" href="#q3-useeffect-的依赖数组与执行时机" aria-label="Permalink to &quot;Q3. `useEffect` 的依赖数组与执行时机？&quot;">​</a></h3><p><strong>要点</strong>：不传依赖 → 每次渲染后都执行；传 <code>[]</code> → 只挂载后执行一次；传 <code>[a, b]</code> → 依赖变化后执行。返回的函数是清理函数，在<strong>下次执行前</strong>与<strong>卸载时</strong>调用。</p><p><strong>深度补充</strong>：<code>useEffect</code> 在<strong>渲染提交（commit）后、浏览器绘制后</strong>异步执行；<code>useLayoutEffect</code> 在<strong>绘制前同步执行</strong>，用于需要同步读取 DOM 布局的场景（避免闪烁）。依赖是<strong>浅比较</strong>，对象/数组字面量每次都变，需 <code>useMemo</code> 稳定。</p><h3 id="q4-useeffect-的闭包陷阱是什么" tabindex="-1">Q4. <code>useEffect</code> 的闭包陷阱是什么？ <a class="header-anchor" href="#q4-useeffect-的闭包陷阱是什么" aria-label="Permalink to &quot;Q4. `useEffect` 的闭包陷阱是什么？&quot;">​</a></h3><p><strong>要点</strong>：<code>useEffect(fn, [])</code> 只执行一次，<code>fn</code> 捕获的是<strong>首次渲染</strong>的 state/props，之后永远看到旧值。修复：把用到的东西写进依赖数组，或用 <code>useRef</code> 保存最新值。</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Timer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">setCount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  useEffect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> setInterval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> setCount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 用函数式更新避免旧值</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> clearInterval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(id);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }, []);                                                       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 依赖为空：只挂载一次</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>深度补充</strong>：<code>setInterval</code> 里若写 <code>setCount(count + 1)</code> 会永远 +1（<code>count</code> 是 0）；用 <code>setCount((c) =&gt; c + 1)</code> 则每次基于最新值。这是&quot;闭包捕获旧值&quot;的经典解决法。</p><h3 id="q5-usememo-与-usecallback-的使用时机" tabindex="-1">Q5. <code>useMemo</code> 与 <code>useCallback</code> 的使用时机？ <a class="header-anchor" href="#q5-usememo-与-usecallback-的使用时机" aria-label="Permalink to &quot;Q5. `useMemo` 与 `useCallback` 的使用时机？&quot;">​</a></h3><p><strong>要点</strong>：<code>useMemo</code> 缓存<strong>计算结果</strong>，<code>useCallback</code> 缓存<strong>函数引用</strong>（等价 <code>useMemo(() =&gt; fn, deps)</code>）。都用于依赖项稳定，避免子组件无效重渲染或重复计算。</p><p><strong>深度补充</strong>：<strong>不要滥用</strong>——缓存本身有成本（存依赖、比较），只有当&quot;计算开销大&quot;或&quot;引用稳定对下游有意义&quot;时才用。常见误用是给所有函数套 <code>useCallback</code> 却没配 <code>React.memo</code>，反而没收益。</p><h3 id="q6-react-memo-usememo-usecallback-如何协同优化" tabindex="-1">Q6. <code>React.memo</code> / <code>useMemo</code> / <code>useCallback</code> 如何协同优化？ <a class="header-anchor" href="#q6-react-memo-usememo-usecallback-如何协同优化" aria-label="Permalink to &quot;Q6. `React.memo` / `useMemo` / `useCallback` 如何协同优化？&quot;">​</a></h3><p><strong>要点</strong>：<code>React.memo</code> 对 props 做浅比较，相等则跳过重渲染；配合 <code>useMemo/useCallback</code> 稳定 props 引用才有效。父组件传入内联对象/函数会破坏 memo。</p><p><strong>深度补充</strong>：三个层次——<code>React.memo</code>（组件级）、<code>useMemo/useCallback</code>（值级）、<code>useState</code> 状态下移/拆分（结构级）。更极致的还有 <code>children</code> 作为 props 透传（&quot;状态提升&quot;的反向技巧）与虚拟化。</p><h3 id="q7-react-fiber-是什么-解决了什么问题" tabindex="-1">Q7. React Fiber 是什么？解决了什么问题？ <a class="header-anchor" href="#q7-react-fiber-是什么-解决了什么问题" aria-label="Permalink to &quot;Q7. React Fiber 是什么？解决了什么问题？&quot;">​</a></h3><p><strong>要点</strong>：Fiber 是 React 16 引入的<strong>可中断的渲染架构</strong>。旧架构递归 diff 无法中断，长任务会卡住主线程；Fiber 把渲染拆成可中断的工作单元（链表结构），配合调度器做<strong>时间切片</strong>，让高优先级更新（如输入）先响应。</p><p><strong>深度补充</strong>：Fiber 节点是链表（<code>child</code>/<code>sibling</code>/<code>return</code> 指针），渲染分两阶段——<strong>render 阶段</strong>（可中断、可丢弃）与 <strong>commit 阶段</strong>（同步、不可中断，真正改 DOM）。<code>useEffect</code> 的回调在 commit 后异步执行，<code>useLayoutEffect</code> 在 commit 中同步执行，正对应两阶段。</p><h3 id="q8-react-的-diff-算法与-key-的作用" tabindex="-1">Q8. React 的 diff 算法与 key 的作用？ <a class="header-anchor" href="#q8-react-的-diff-算法与-key-的作用" aria-label="Permalink to &quot;Q8. React 的 diff 算法与 key 的作用？&quot;">​</a></h3><p><strong>要点</strong>：React 的 diff 是 O(n) 启发式：同层比较、类型不同直接整棵替换、用 <strong>key</strong> 匹配同层列表元素。key 稳定能让 React 复用节点状态，提升性能；用索引当 key 在列表增删/排序时会导致状态错位。</p><p><strong>深度补充</strong>：<code>key</code> 让 React 知道&quot;哪个元素是哪个&quot;，从而移动而非重建。用 index 作 key，在头部插入元素时，后续元素的 index 全变，React 会误判为&quot;内容变了&quot;而重建。列表若含输入框等<strong>内部状态</strong>，错误 key 会造成内容串位。</p><h3 id="q9-react-的并发特性-concurrent-有哪些" tabindex="-1">Q9. React 的并发特性（Concurrent）有哪些？ <a class="header-anchor" href="#q9-react-的并发特性-concurrent-有哪些" aria-label="Permalink to &quot;Q9. React 的并发特性（Concurrent）有哪些？&quot;">​</a></h3><p><strong>要点</strong>：React 18 的并发核心是<strong>可中断渲染 + 优先级调度</strong>。代表 API：<code>useTransition</code>（把非紧急更新标记为过渡）、<code>useDeferredValue</code>（延迟某个值）、<code>Suspense</code>（挂起等待）、<code>startTransition</code>。</p><p><strong>深度补充</strong>：<code>useTransition</code> 返回 <code>[isPending, startTransition]</code>，把&quot;列表筛选&quot;这类耗时更新标为低优先级，保持输入框即时响应。<code>useDeferredValue</code> 与 <code>useTransition</code> 的区别：前者延迟<strong>值</strong>、后者包装<strong>更新</strong>，前者更适合&quot;派生展示&quot;。</p><h3 id="q10-usesyncexternalstore-用来做什么" tabindex="-1">Q10. <code>useSyncExternalStore</code> 用来做什么？ <a class="header-anchor" href="#q10-usesyncexternalstore-用来做什么" aria-label="Permalink to &quot;Q10. `useSyncExternalStore` 用来做什么？&quot;">​</a></h3><p><strong>要点</strong>：让外部状态（Redux、Zustand、浏览器 API）安全接入 React 并发渲染。它订阅外部 store，并保证返回的 <code>getSnapshot</code> 在并发下<strong>一致</strong>，避免撕裂（tearing）。</p><p><strong>深度补充</strong>：参数是 <code>(subscribe, getSnapshot, getServerSnapshot)</code>。<code>getSnapshot</code> 必须返回<strong>缓存过的</strong>稳定引用（否则每次新对象会无限重渲染）。这是第三方状态库在 React 18 中的标准接入方式。</p><h3 id="q11-context-的性能问题与优化" tabindex="-1">Q11. Context 的性能问题与优化？ <a class="header-anchor" href="#q11-context-的性能问题与优化" aria-label="Permalink to &quot;Q11. Context 的性能问题与优化？&quot;">​</a></h3><p><strong>要点</strong>：Context 的值变化会让<strong>所有</strong>消费组件重渲染，无法按字段订阅。优化：拆分多个 Context、用 <code>useMemo</code> 稳定 value、把不需订阅的组件移出 Provider。</p><p><strong>深度补充</strong>：更彻底的方案是&quot;选择器模式&quot;——用 <code>use-context-selector</code> 或换成 Zustand/Jotai 这类能按字段订阅的状态库。<code>React.memo</code> 也无法阻止 Context 变化引发的重渲染（它绕过 props 比较）。</p><h3 id="q12-react-19-有哪些值得关注的新特性" tabindex="-1">Q12. React 19 有哪些值得关注的新特性？ <a class="header-anchor" href="#q12-react-19-有哪些值得关注的新特性" aria-label="Permalink to &quot;Q12. React 19 有哪些值得关注的新特性？&quot;">​</a></h3><p><strong>要点</strong>：<code>use</code> API（在组件里读 Promise/Context，可条件调用）、Actions（表单 action 自动处理 pending/错误）、<code>useOptimistic</code>（乐观更新）、<code>useFormStatus</code>/<code>useActionState</code>、<code>ref</code> 可直接作为 prop（免 <code>forwardRef</code>）、文档元数据（<code>&lt;title&gt;</code>/<code>&lt;meta&gt;</code>）自动提升、原生支持异步脚本。</p><p><strong>深度补充</strong>：<code>use(promise)</code> 配合 <code>Suspense</code> 简化数据读取；<code>useOptimistic</code> 让交互即时反馈、失败后回滚，非常适合 IM/点赞等场景（命中 #8 鹏开信息）。这些组合体现了&quot;把数据流与副作用内建化&quot;的方向。</p><h3 id="q13-受控组件与非受控组件的区别" tabindex="-1">Q13. 受控组件与非受控组件的区别？ <a class="header-anchor" href="#q13-受控组件与非受控组件的区别" aria-label="Permalink to &quot;Q13. 受控组件与非受控组件的区别？&quot;">​</a></h3><p><strong>要点</strong>：受控组件的值由 React state 驱动（<code>value</code> + <code>onChange</code>），可实时校验、可编程；非受控组件用 <code>ref</code> 读 DOM 值（<code>defaultValue</code>），书写简洁但不可控。</p><p><strong>深度补充</strong>：复杂表单推荐受控 + 状态库（如 React Hook Form 用非受控 + 订阅做性能优化）。受控组件在大表单下会因频繁 setState 而卡顿，可用 <code>useRef</code> + 订阅降低渲染频率。</p><h3 id="q14-react-常见的性能优化手段有哪些" tabindex="-1">Q14. React 常见的性能优化手段有哪些？ <a class="header-anchor" href="#q14-react-常见的性能优化手段有哪些" aria-label="Permalink to &quot;Q14. React 常见的性能优化手段有哪些？&quot;">​</a></h3><p><strong>要点</strong>：<code>React.memo</code> + <code>useMemo/useCallback</code> 减少重渲染；列表虚拟化（react-window）；<code>key</code> 稳定；状态下移/拆分；<code>useTransition</code> 降优先级；代码分割 <code>React.lazy</code> + <code>Suspense</code>；<code>useDeferredValue</code>。</p><p><strong>深度补充</strong>：先用 <strong>React DevTools Profiler</strong> 定位真正的热点，再对症优化——盲目 memo 会增加比较成本。大列表（如 #7 大屏、#1 监控列表）优先虚拟化而非 memo。</p><h2 id="二、vue-响应式与编译" tabindex="-1">二、Vue：响应式与编译 <a class="header-anchor" href="#二、vue-响应式与编译" aria-label="Permalink to &quot;二、Vue：响应式与编译&quot;">​</a></h2><h3 id="q15-vue3-响应式原理-为什么用-proxy-替代-defineproperty" tabindex="-1">Q15. Vue3 响应式原理？为什么用 Proxy 替代 defineProperty？ <a class="header-anchor" href="#q15-vue3-响应式原理-为什么用-proxy-替代-defineproperty" aria-label="Permalink to &quot;Q15. Vue3 响应式原理？为什么用 Proxy 替代 defineProperty？&quot;">​</a></h3><p><strong>要点</strong>：Vue3 用 <code>Proxy</code> 拦截对象的 <code>get/set/has/delete/ownKeys</code>，在 <code>get</code> 中 <code>track</code> 收集依赖、<code>set</code> 中 <code>trigger</code> 派发更新，且<strong>惰性</strong>递归（访问到哪层才代理哪层）。</p><p><strong>深度补充</strong>：<code>defineProperty</code> 初始化时递归劫持已知键，导致新增/删除属性、数组索引、<code>Map/Set</code> 检测不到（Vue2 需 <code>Vue.set</code>）；<code>Proxy</code> 全能拦截且初始化成本低。代价是兼容性下限（不支持 IE）。</p><table tabindex="0"><thead><tr><th>维度</th><th>Vue2 · defineProperty</th><th>Vue3 · Proxy</th></tr></thead><tbody><tr><td>新增/删除属性</td><td>检测不到</td><td>可检测</td></tr><tr><td>初始化</td><td>递归遍历所有属性（慢）</td><td>惰性、按需（快）</td></tr><tr><td>Map/Set</td><td>不支持</td><td>支持</td></tr></tbody></table><h3 id="q16-ref-与-reactive-如何选型" tabindex="-1">Q16. <code>ref</code> 与 <code>reactive</code> 如何选型？ <a class="header-anchor" href="#q16-ref-与-reactive-如何选型" aria-label="Permalink to &quot;Q16. `ref` 与 `reactive` 如何选型？&quot;">​</a></h3><p><strong>要点</strong>：<code>reactive</code> 只接受对象/数组，返回 Proxy，解构或整体替换会丢响应性；<code>ref</code> 可包装任意值（含基本类型），经 <code>.value</code> 访问，可整体替换。基本类型必须用 <code>ref</code>。</p><p><strong>深度补充</strong>：<code>reactive</code> 解构丢响应性需用 <code>toRefs</code>；<code>ref</code> 在模板中自动解包（无需 <code>.value</code>），在 JS 中需 <code>.value</code>。推荐<strong>统一用 <code>ref</code></strong>，避免 <code>reactive</code> 的解构/替换坑。<code>shallowRef</code>/<code>shallowReactive</code> 用于大对象只做浅响应。</p><h3 id="q17-computed-与-watch-的区别" tabindex="-1">Q17. <code>computed</code> 与 <code>watch</code> 的区别？ <a class="header-anchor" href="#q17-computed-与-watch-的区别" aria-label="Permalink to &quot;Q17. `computed` 与 `watch` 的区别？&quot;">​</a></h3><p><strong>要点</strong>：<code>computed</code> 是<strong>派生值</strong>，有缓存、依赖不变不重算、必须同步返回；<code>watch</code> 是<strong>副作用</strong>，依赖变化时执行、可异步、可拿到新旧值。计算属性用于&quot;展示派生数据&quot;，watch 用于&quot;变化后做事情&quot;。</p><p><strong>深度补充</strong>：<code>computed</code> 基于依赖自动追踪（惰性求值）；<code>watch</code> 需显式指定源，<code>{ immediate: true, deep: true }</code> 控制时机与深度。<code>watchEffect</code> 自动追踪依赖、立即执行一次，适合&quot;无需旧值&quot;的场景。<strong>不要在 computed 里做副作用</strong>（如发请求）。</p><h3 id="q18-nexttick-的原理与用途" tabindex="-1">Q18. <code>nextTick</code> 的原理与用途？ <a class="header-anchor" href="#q18-nexttick-的原理与用途" aria-label="Permalink to &quot;Q18. `nextTick` 的原理与用途？&quot;">​</a></h3><p><strong>要点</strong>：Vue 的 DOM 更新是<strong>异步批处理</strong>——数据变化后不会立刻更新 DOM，而是把 watcher 推入队列，在微任务中统一 flush。<code>nextTick</code> 返回一个 Promise，在 DOM 更新完成后执行回调。</p><p><strong>深度补充</strong>：<code>nextTick</code> 本质是把回调放进 flush 之后的队列（基于 <code>Promise.then</code> 的微任务）。用途：数据变了立刻读新 DOM（获取更新后的尺寸、滚动位置）。</p><h3 id="q19-v-model-的原理" tabindex="-1">Q19. <code>v-model</code> 的原理？ <a class="header-anchor" href="#q19-v-model-的原理" aria-label="Permalink to &quot;Q19. `v-model` 的原理？&quot;">​</a></h3><p><strong>要点</strong>：<code>v-model</code> 是语法糖。<code>&lt;input v-model=&quot;x&quot;&gt;</code> 展开为 <code>:value=&quot;x&quot;</code> + <code>@input=&quot;x = $event.target.value&quot;</code>；在自定义组件上展开为 <code>:modelValue</code> + <code>@update:modelValue</code>。</p><p><strong>深度补充</strong>：Vue3 支持多个 <code>v-model</code>（<code>v-model:title</code> / <code>v-model:content</code>）与 <code>.sync</code> 的替代。<code>.lazy</code> 改为 change 时同步、<code>.number</code> 转数字、<code>.trim</code> 去空格是修饰符。</p><h3 id="q20-vue-的生命周期钩子与执行顺序" tabindex="-1">Q20. Vue 的生命周期钩子与执行顺序？ <a class="header-anchor" href="#q20-vue-的生命周期钩子与执行顺序" aria-label="Permalink to &quot;Q20. Vue 的生命周期钩子与执行顺序？&quot;">​</a></h3><p><strong>要点</strong>：创建（<code>setup</code>）、挂载（<code>onBeforeMount</code> → <code>onMounted</code>）、更新（<code>onBeforeUpdate</code> → <code>onUpdated</code>）、卸载（<code>onBeforeUnmount</code> → <code>onUnmounted</code>）。父子组件挂载是&quot;子先 mounted&quot;，卸载是&quot;父先 unmounted&quot;。</p><p><strong>深度补充</strong>：<code>setup</code> 在所有 <code>beforeCreate/created</code> 之前执行，替代了二者。<code>onMounted</code> 中可访问 DOM；请求数据常放这里。组合式 API 用 <code>onXxx</code> 注册，需在 <code>setup</code> 同步阶段调用（否则无法绑定到当前实例）。</p><h3 id="q21-vue-的模板编译与-patch-过程" tabindex="-1">Q21. Vue 的模板编译与 patch 过程？ <a class="header-anchor" href="#q21-vue-的模板编译与-patch-过程" aria-label="Permalink to &quot;Q21. Vue 的模板编译与 patch 过程？&quot;">​</a></h3><p><strong>要点</strong>：模板编译分三步——<code>parse</code>（生成 AST）、<code>transform</code>（优化，标记静态节点/<code>PatchFlags</code>）、<code>generate</code>（生成 render 函数）。运行时通过 <code>PatchFlags</code> 精确 diff 动态节点，静态节点被提升（<code>hoistStatic</code>）跳过 diff。</p><p><strong>深度补充</strong>：Vue3 的 <code>PatchFlags</code>（如 TEXT/CLASS/PROPS）让更新只比对<strong>会变</strong>的部分；<code>Block Tree</code> 把动态节点收集成数组，diff 时只遍历动态节点，复杂度从整棵树降到动态节点数。这是 Vue3 编译优化的核心。</p><h3 id="q22-vue3-相比-vue2-的主要改进" tabindex="-1">Q22. Vue3 相比 Vue2 的主要改进？ <a class="header-anchor" href="#q22-vue3-相比-vue2-的主要改进" aria-label="Permalink to &quot;Q22. Vue3 相比 Vue2 的主要改进？&quot;">​</a></h3><p><strong>要点</strong>：组合式 API（逻辑复用与组织）、<code>Proxy</code> 响应式（更全更快）、编译优化（PatchFlags/静态提升/Block）、更小的 Tree-shaking 体积、<code>Fragment</code>/<code>Teleport</code>/<code>Suspense</code>、更好的 TS 支持、性能提升。</p><p><strong>深度补充</strong>：<code>defineAsyncComponent</code> 支持异步组件与 Suspense 配合；<code>Teleport</code> 把内容渲染到 DOM 其他位置（模态框、通知——常用于 #7 大屏悬浮面板、#8 全局消息）。</p><h3 id="q23-vue-的常见性能优化手段" tabindex="-1">Q23. Vue 的常见性能优化手段？ <a class="header-anchor" href="#q23-vue-的常见性能优化手段" aria-label="Permalink to &quot;Q23. Vue 的常见性能优化手段？&quot;">​</a></h3><p><strong>要点</strong>：<code>v-if</code> 与 <code>v-show</code> 按切换频率选（频繁用 show）；<code>v-for</code> 必须配稳定 <code>key</code>；避免 <code>v-if</code> 与 <code>v-for</code> 同层；长列表虚拟滚动；<code>shallowRef</code> 处理大对象；<code>computed</code> 缓存派生值；组件异步加载。</p><p><strong>深度补充</strong>：<code>v-for</code> 与 <code>v-if</code> 同层时 Vue3 中 <code>v-if</code> 优先级更高（Vue2 反之），可能报错或逻辑错误，应把 <code>v-if</code> 移到外层。大屏/大表格场景优先虚拟化。</p><h2 id="三、react-与-vue-对比" tabindex="-1">三、React 与 Vue 对比 <a class="header-anchor" href="#三、react-与-vue-对比" aria-label="Permalink to &quot;三、React 与 Vue 对比&quot;">​</a></h2><h3 id="q24-react-与-vue-的心智模型差异" tabindex="-1">Q24. React 与 Vue 的心智模型差异？ <a class="header-anchor" href="#q24-react-与-vue-的心智模型差异" aria-label="Permalink to &quot;Q24. React 与 Vue 的心智模型差异？&quot;">​</a></h3><p><strong>要点</strong>：React 是&quot;<strong>函数式 + 不可变</strong>&quot;——UI = f(state)，靠 <code>setState</code> 触发重渲染，一切皆 JS（JSX）；Vue 是&quot;<strong>响应式 + 可变</strong>&quot;——直接改数据即自动更新，模板自动追踪依赖。</p><p><strong>深度补充</strong>：React 需手动优化（memo/useMemo），Vue 依赖自动追踪更&quot;省心&quot;但黑盒感更强。React 的 <code>setState</code> 是&quot;替换&quot;，Vue 是&quot;就地修改&quot;。二者都收敛到&quot;数据驱动视图&quot;，只是数据更新的表达方式不同。</p><table tabindex="0"><thead><tr><th>维度</th><th>React</th><th>Vue</th></tr></thead><tbody><tr><td>数据</td><td>不可变，<code>setState</code> 替换</td><td>可变，直接赋值</td></tr><tr><td>视图</td><td>JSX / 纯 JS</td><td>模板 + 指令（也支持 JSX）</td></tr><tr><td>更新</td><td>显式触发</td><td>自动追踪依赖</td></tr><tr><td>优化</td><td>手动（memo/useMemo）</td><td>编译期 + 自动追踪</td></tr><tr><td>逻辑复用</td><td>自定义 Hook</td><td>组合式函数（Composition API）</td></tr></tbody></table><h3 id="q25-双栈工程师如何回答-你更熟哪个" tabindex="-1">Q25. 双栈工程师如何回答&quot;你更熟哪个&quot;？ <a class="header-anchor" href="#q25-双栈工程师如何回答-你更熟哪个" aria-label="Permalink to &quot;Q25. 双栈工程师如何回答&quot;你更熟哪个&quot;？&quot;">​</a></h3><p><strong>要点</strong>：不要贬低任一框架，强调&quot;<strong>心智模型可迁移</strong>&quot;。答：React 的 Hooks 与 Vue 的组合式 API 都是&quot;用函数组织逻辑&quot;，响应式与不可变更新的差异我都能驾驭；我做过<strong>双栈同构组件库</strong>，同一套设计 token 与交互契约在两端落地。</p><p><strong>深度补充</strong>：补充具体迁移经验——如&quot;React 的 <code>useEffect</code> 依赖数组与 Vue 的 <code>watch</code> 依赖源，本质都是&#39;声明依赖以决定副作用时机&#39;&quot;。这种类比能立刻体现双栈深度（命中 9 份 JD 的多数双栈要求）。</p><h2 id="面试要点" tabindex="-1">面试要点 <a class="header-anchor" href="#面试要点" aria-label="Permalink to &quot;面试要点&quot;">​</a></h2><ol><li><strong>Hooks 为什么不能条件调用？</strong> 状态按调用顺序存在链表里，顺序变了状态错位。</li><li><strong><code>useEffect</code> 闭包陷阱？</strong> 依赖 <code>[]</code> 时永远看到首次的值；用依赖数组或函数式更新/<code>useRef</code> 修。</li><li><strong>Fiber 解决什么？</strong> 可中断渲染 + 时间切片，避免长任务卡住主线程；分 render（可中断）与 commit（不可中断）两阶段。</li><li><strong>key 的作用？</strong> 帮助 React/Vue 在同层列表中复用节点与内部状态；索引作 key 在增删时会错位。</li><li><strong>Vue3 响应式为什么用 Proxy？</strong> 覆盖新增/删除/数组索引/Map/Set，且惰性代理降低初始化成本。</li><li><strong><code>ref</code> 还是 <code>reactive</code>？</strong> 基本类型必须 ref；推荐统一 ref，避免 reactive 解构丢响应性。</li><li><strong><code>computed</code> 与 <code>watch</code>？</strong> computed 是带缓存的派生值（无副作用），watch 是变化后执行的副作用。</li><li><strong>双栈怎么答？</strong> 强调心智模型可迁移 + 双栈同构组件库的具体经验，不贬低任一框架。</li></ol>',86)])])}const g=o(c,[["render",d]]);export{p as __pageData,g as default};
